 static Sprite Texture(string name,int width,int height,Color[] pixels,int border=0){string path=Folder+name+".png";var texture=new Texture2D(width,height,TextureFormat.RGBA32,false);texture.SetPixels(pixels);texture.Apply();File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.spritePixelsPerUnit=100;importer.filterMode=FilterMode.Point;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.spriteBorder=new Vector4(border,border,border,border);importer.alphaIsTransparency=true;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 static Sprite Frame(string name,Color fill,bool pressed=false){const int w=32,h=32;var pixels=new Color[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int edge=Mathf.Min(x,y,w-1-x,h-1-y);bool corner=(x<2&&y<2)||(x>=w-2&&y<2)||(x<2&&y>=h-2)||(x>=w-2&&y>=h-2);if(corner){pixels[y*w+x]=Color.clear;continue;}Color c=fill;if(edge<=1)c=Ink;else if(edge==2)c=y>h/2?Color.Lerp(fill,Color.white,.45f):Color.Lerp(fill,Ink,.35f);else if(edge==3)c=Color.Lerp(fill,Ink,.15f);if((x==4||x==w-5)&&(y==4||y==h-5))c=Color.Lerp(fill,Ink,.55f);if(pressed&&y==h-4)c=Color.Lerp(fill,Ink,.45f);pixels[y*w+x]=c;}return Texture(name,w,h,pixels,6);}
 static Sprite Icon(string name,string[] pattern){int w=16;var pixels=new Color[256];for(int row=0;row<Mathf.Min(16,pattern.Length);row++)for(int x=0;x<Mathf.Min(w,pattern[row].Length);x++){char c=pattern[row][x];pixels[(15-row)*16+x]=c=='#'?Ink:c=='g'?Gold:c=='w'?Cream:c=='b'?Blue:c=='r'?new Color32(220,119,91,255):c=='m'?new Color32(127,182,150,255):Color.clear;}return Texture("Icon-"+name,16,16,pixels);}
